// Surface a generated result back into the chat thread.
const { artifact_id } = await anna.chat.append_artifact({
  artifact: {
    kind: "summary",
    summary: "Generated a 3-paragraph recap of the uploaded PDF",
    payload_ref: savedKey,   // e.g. an anna.storage.set / anna.files key
    data: { paragraphs: 3, words: 412 },
  },
});
console.log("appended", artifact_id); // app-1a2b3c4d-1730000000

// Emit an assistant-authored line. NOTE: not persisted yet (Phase 3).
const { message_id } = await anna.chat.write_message({
  role: "assistant",
  content: "Done — I exported your report to the Files panel.",
});
// message_id === "msg-1730000000123"; the host broadcasts a
// `chat_message_from_app` event for the chat UI to render in-session.

// NOT YET IMPLEMENTED — this will reject.
try {
  await anna.chat.read_history();
} catch (err) {
  // err.code === "not_implemented"  ("chat.read_history is Phase 3")
}
